                  .ErrorCase("401", CreateErrorCase("Unauthorized - authentication required.", (errorReason, context) => new RestServiceErrorException(errorReason, context)))
                  .ErrorCase("403", CreateErrorCase("Forbidden - insufficient permissions to process the request.", (errorReason, context) => new RestServiceErrorException(errorReason, context)))
                  .ErrorCase("422", CreateErrorCase("Unprocessable Entity - a request validation error.", (errorReason, context) => new RestServiceErrorException(errorReason, context)))
                  .ErrorCase("500", CreateErrorCase("Internal Server Error - the server could not process the request.", (errorReason, context) => new RestServiceErrorException(errorReason, context))))
              .ExecuteAsync(cancellationToken).ConfigureAwait(false);
    }
}